"""Bounded LuaLaTeX compilation of TeX generated by the authenticated web gateway."""

import asyncio
import os
import re
import shutil
import signal
import tempfile
from pathlib import Path

MAX_PDF_BYTES = 4 * 1024 * 1024
MAX_TEX_BYTES = 1024 * 1024
TIMEOUT_SECONDS = 40
_running = asyncio.Semaphore(1)


class CompileError(Exception):
    def __init__(self, code: str, status: int = 422):
        self.code = code
        self.status = status
        super().__init__(code)


async def compile_report(tex: str) -> bytes:
    if len(tex.encode("utf-8")) > MAX_TEX_BYTES:
        raise CompileError("EXPORT_TOO_LARGE", 413)
    executable = shutil.which(os.environ.get("LUALATEX_COMMAND", "lualatex"))
    if not executable:
        raise CompileError("TEX_COMPILER_UNAVAILABLE", 503)
    if _running.locked():
        raise CompileError("TEX_COMPILER_BUSY", 429)
    async with _running:
        with tempfile.TemporaryDirectory(prefix="mn-report-") as folder:
            root = Path(folder)
            (root / "report.tex").write_text(tex, encoding="utf-8", newline="\n")
            # Never expose the service API key or cloud credentials to the TeX child.
            env = {
                key: value
                for key, value in os.environ.items()
                if key
                in {
                    "PATH",
                    "SYSTEMROOT",
                    "WINDIR",
                    "LANG",
                    "LC_ALL",
                    "TEXMFCACHE",
                    "TEXMFVAR",
                    "TEXMFCONFIG",
                    "OSFONTDIR",
                    "FONTCONFIG_PATH",
                }
            }
            # Luaotfload reads Unicode data by absolute TEXMF path; `p` blocks that on Debian.
            # Restricted reads plus fixed generated TeX, no secrets, read-only root and no egress
            # provide the boundary. Output remains restricted to the per-request directory.
            env.update(
                {
                    "HOME": folder,
                    "TMPDIR": folder,
                    "TEMP": folder,
                    "TMP": folder,
                    "openin_any": "r",
                    "openout_any": "p",
                    "shell_escape": "f",
                }
            )
            log = root / "process.log"
            with log.open("wb") as output:
                process = await asyncio.create_subprocess_exec(
                    executable,
                    "--no-shell-escape",
                    "--nosocket",
                    "-interaction=nonstopmode",
                    "-halt-on-error",
                    "-file-line-error",
                    "report.tex",
                    cwd=folder,
                    env=env,
                    stdout=output,
                    stderr=asyncio.subprocess.STDOUT,
                    start_new_session=os.name != "nt",
                )
                try:
                    await asyncio.wait_for(process.wait(), TIMEOUT_SECONDS)
                except (TimeoutError, asyncio.CancelledError):
                    if process.returncode is None:
                        if os.name == "nt":
                            process.kill()
                        else:
                            os.killpg(process.pid, signal.SIGKILL)
                        await process.wait()
                    if asyncio.current_task() and asyncio.current_task().cancelling():
                        raise
                    raise CompileError("TEX_COMPILE_TIMEOUT", 504) from None
            if process.returncode != 0:
                raise CompileError("TEX_COMPILE_FAILED")
            path = root / "report.pdf"
            if not path.is_file() or path.stat().st_size > MAX_PDF_BYTES:
                raise CompileError("EXPORT_TOO_LARGE", 413)
            # LuaTeX's own summary counts compressed PDF pages reliably.
            summary = log.read_bytes()[-65536:]
            pages = re.search(rb"Output written on report\.pdf \((\d+) pages?[,)]", summary)
            if not pages or int(pages[1]) > 50:
                raise CompileError("EXPORT_TOO_LARGE", 413)
            result = path.read_bytes()
            if not result.startswith(b"%PDF-"):
                raise CompileError("TEX_COMPILE_FAILED")
            return result
